def _secure_tables() -> None:
    tenant = "organization_id=nullif(current_setting('app.organization_id',true),'')::uuid"
    for table in (
        "evaluation_candidates",
        "evaluation_cases",
        "evaluation_case_revisions",
        "evaluation_dataset_versions",
        "evaluation_dataset_cases",
    ):
        admin = f"""EXISTS(SELECT 1 FROM memberships m JOIN users u ON u.id=m.user_id
            WHERE m.organization_id={table}.organization_id
            AND m.id=nullif(current_setting('app.membership_id',true),'')::uuid
            AND m.is_active AND u.is_active AND m.role='ADMIN')"""
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
        permissions = (
            "SELECT,INSERT,UPDATE"
            if table in ("evaluation_candidates", "evaluation_cases")
            else "SELECT,INSERT"
        )
        op.execute(f"GRANT {permissions} ON {table} TO app_runtime")
        op.execute(
            f"CREATE POLICY {table}_scope ON {table} TO app_runtime "
            f"USING ({tenant} AND {admin}) WITH CHECK ({tenant} AND {admin})"
        )
        if table not in ("evaluation_candidates", "evaluation_cases"):
            op.execute(
                f"CREATE TRIGGER {table}_immutable BEFORE UPDATE OR DELETE ON {table} "
                "FOR EACH ROW EXECUTE FUNCTION guard_daily_reporting_fact()"
            )
    op.execute("""CREATE FUNCTION guard_evaluation_metadata() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            IF TG_OP='DELETE' THEN RAISE EXCEPTION 'evaluation lineage is retained'; END IF;
            IF TG_TABLE_NAME='evaluation_candidates' THEN
                IF (to_jsonb(NEW)-'version'-'status'-'context') IS DISTINCT FROM
                   (to_jsonb(OLD)-'version'-'status'-'context') OR
                   (NEW.context IS DISTINCT FROM OLD.context AND NEW.context IS NOT NULL) THEN
                    RAISE EXCEPTION 'candidate lineage is immutable';
                END IF;
            ELSIF (to_jsonb(NEW)-'current_version') IS DISTINCT FROM
                  (to_jsonb(OLD)-'current_version') THEN
                RAISE EXCEPTION 'case identity and split are immutable';
            END IF;
            RETURN NEW;
        END $$""")
    for table in ("evaluation_candidates", "evaluation_cases"):
        op.execute(
            f"CREATE TRIGGER {table}_metadata BEFORE UPDATE OR DELETE ON {table} "
            "FOR EACH ROW EXECUTE FUNCTION guard_evaluation_metadata()"
        )


